# owner: platform
"""Plain text absence notices for parents."""

from typing import List

from rosterkit.models import Mark, Student


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} does not "
                f"belong to {student.student_id}"
            )


def _absent_days(marks: List[Mark]) -> list:
    absent = [
        item for item in marks if item.status == "absent"
    ]
    days = {item.day for item in absent}
    return sorted(days)


def _count_phrase(count: int) -> str:
    return "1 day" if count == 1 else f"{count} days"


# ---
def build_absence_notice(student: Student, marks) -> str:
    """Short notice naming the student and absent dates."""
    marks = list(marks)
    _check_owner(student, marks)
    days = _absent_days(marks)
    if not days:
        raise ValueError("no absences to report")
    return _format_notice(student, days)


def _date_lines(days: list) -> str:
    lines = [f"- {day.isoformat()}" for day in days]
    return "\n".join(lines)


def _format_notice(student: Student, days: list) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = _count_phrase(len(days))
    return (
        f"Dear parent or guardian,\n\n"
        f"{name} was absent for {count}:\n"
        f"{_date_lines(days)}\n"
    )
